def longest_serial_run(serials):
    present = set(serials)
    best = [0, 0]
    for x in present:
        if x - 1 in present:
            continue
        y = x
        while y + 1 in present:
            y += 1
        length = y - x + 1
        if length > best[1] or (length == best[1] and x < best[0]):
            best = [x, length]
    return best

